\newcommand{\Z}{\mathbb{Z}}
\newcommand{\Q}{\mathbb{Q}}
\newcommand{\ceilhalf}[1]{\lceil #1/2\rceil}

\title[What a Sum Remembers]{What a Sum Remembers: Readable Type Channels for Pairs of Residues,
the Half-Conductor Law, and Reducible Polynomials}
\author{Aristotle (Harmonic)}
\date{September 26, 2026}

\begin{document}

\begin{abstract}
Let $p,q$ be units modulo an integer $m$ and suppose only the \emph{hinted view}
$(p+q \bmod m,\ pq \bmod m)$ is visible. Which functions of the residues---which \emph{type
maps}---can be read off, in the sense that the unordered pair of types $\{f(p),f(q)\}$ is
determined? Over a field every type map is readable. Over $\Z/m\Z$ we give a complete answer.
(i) The view determines the unordered pair exactly when $m\in\{0,1,2,\ell,2\ell\}$ with $\ell$ an
odd prime; the only obstructions are square-zero elements and Chinese-remainder matching
ambiguity. (ii) At a prime power $\ell^k$ the pair is determined modulo $\ell^{\ceilhalf{k}}$ and
no finer, and a type map is readable iff it factors through the residue modulo
$\ell^{\ceilhalf{k}}$; pairs with $p\not\equiv q\pmod\ell$ lose nothing. (iii) Readable channels are
closed under coarsening but not under joins, and on a product ring they come from a single
factor. (iv) For every $m\ge1$, a type map is readable iff, for one prime power $\ell^k\,\|\,m$, it
depends only on the residue modulo $\ell^{\ceilhalf{k}}$. At conductor $8$ this refutes a proposed
explanation of an empirically sum-sufficient dial (the primes $17,41$ versus $13,29$), shows that a
dial at $8$ is readable iff it is invariant under multiplication by $5$, that exactly one of the
three quadratic channels $\Q(i),\Q(\sqrt2),\Q(\sqrt{-2})$ of $\Q(\zeta_8)$ is readable, and that the
\'etale type of the reducible polynomial $(x^2+1)(x^2-2)$ is not readable although its first factor
is.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The question}
Many arithmetic invariants of a prime $p$ are functions of $p$ modulo a fixed \emph{conductor} $m$:
$\left(\frac{-1}{p}\right)$ depends on $p\bmod 4$, $\left(\frac{2}{p}\right)$ on $p\bmod 8$, and by the
Kronecker--Weber theorem the splitting type of $p$ in any abelian number field depends on $p$
modulo the conductor of the field. We call any function $f:(\Z/m\Z)^\times\to B$ a \emph{type map}
(\emph{dial}, \emph{channel}) of conductor $m$.

Suppose two primes $p,q\nmid m$ are hidden and only $s\equiv p+q$, $n\equiv pq \pmod m$ are seen---the
situation of a semiprime $N=pq$ together with a hint on $p+q$ modulo $m$. \emph{For which type maps
$f$ does $(s,n)$ determine $\{f(p),f(q)\}$?} Over a field the view determines the roots of
$x^2-sx+n$ and hence everything. Over $\Z/m\Z$ the same quadratic may factor in several ways.

\subsection{Motivation}
An empirical study of six Galois dials ($S_3$ at conductors $31$ and $23$, $A_4$ at $9$, $D_4$ at $8$,
$F_{20}$ at $5$, $C_5$ at $11$) found that most were ``combination-required'' while the $D_4$ dial
at conductor $8$ appeared \emph{sum-sufficient}. The proposed explanation was that, given
$N=pq\bmod 8$, the residue $(p+q)\bmod 8$ determines $p\bmod 8$ and $q\bmod 8$ via $q\equiv Np^{-1}$.
We show this is false and replace it by exact theorems valid at every conductor.

\subsection{Results}
\begin{enumerate}[label=(\arabic*)]
\item Conductor classification (Theorem~\ref{thm:class}).
\item Half-conductor law, sharpness, and classification at prime powers
(Theorems~\ref{thm:half}, \ref{thm:sharp}, \ref{thm:ppclass}); Hensel refinement
(Theorem~\ref{thm:hensel}).
\item Conductor $8$: refutation, exact criterion, quadratic channels, reducible polynomials
(Section~\ref{sec:eight}).
\item Join failure and the single-factor law (Section~\ref{sec:join}).
\item General classification at every conductor (Theorem~\ref{thm:general}).
\end{enumerate}

\section{Definitions and first properties}
Throughout, $R$ is a commutative ring with unit group $R^\times$.

\begin{definition}
$R$ is \emph{Vieta-injective} if for all $p,q,p',q'\in R^\times$, $p+q=p'+q'$ and $pq=p'q'$ imply
$(p,q)=(p',q')$ or $(p,q)=(q',p')$.
\end{definition}

\begin{definition}
A type map $f:R^\times\to B$ is \emph{sum-sufficient} (\emph{readable}) if for all
$p,q,p',q'\in R^\times$ with $p+q=p'+q'$ and $pq=p'q'$ the unordered pairs $\{f(p),f(q)\}$ and
$\{f(p'),f(q')\}$ coincide.
\end{definition}

The value $(p+q,pq)$ is the \emph{cell} of $\{p,q\}$; a cell is \emph{colliding} if it hosts more
than one unordered pair.

\begin{proposition}[Universality]
$R$ is Vieta-injective iff the identity of $R^\times$ is readable, iff every type map on $R^\times$
is readable.
\end{proposition}

\begin{proposition}[Coarsening]\label{prop:coarse}
If $f$ is readable and $g:B\to C$ is any map, then $g\circ f$ is readable.
\end{proposition}

\begin{proposition}[Pullback]\label{prop:pull}
If $\varphi:R\to S$ is a ring homomorphism and $g:S^\times\to B$ is readable, then
$g\circ\varphi^\times$ is readable.
\end{proposition}
\begin{proof}
Ring homomorphisms preserve equalities of sums and of products.
\end{proof}

\begin{proposition}\label{prop:inj}
A readable injective type map forces $R$ to be Vieta-injective. Both notions are invariant under
ring isomorphism.
\end{proposition}

\section{The conductor classification}

\begin{theorem}[Domains]\label{thm:domain}
In an integral domain $D$, $p+q=p'+q'$ and $pq=p'q'$ imply $\{p,q\}=\{p',q'\}$. In particular
$\Z$ and $\Z/\ell$ ($\ell$ prime) are Vieta-injective, and every type map of prime conductor is
readable.
\end{theorem}
\begin{proof}
The identity
\begin{equation}\label{eq:key}
(p-p')(p-q') = p\bigl((p+q)-(p'+q')\bigr) - (pq-p'q')
\end{equation}
shows $(p-p')(p-q')=0$; so $p=p'$ or $p=q'$, and the remaining element follows by cancellation.
\end{proof}

\begin{theorem}[Nilpotent obstruction]\label{thm:nil}
If $a\neq0$ and $a^2=0$ in $R$, then the unit pairs $\{1,1\}$ and $\{1+a,1-a\}$ share the cell
$(2,1)$; hence $R$ is not Vieta-injective.
\end{theorem}

\begin{theorem}[Matching obstruction]\label{thm:match}
If $u_1\neq v_1$ in $R_1^\times$ and $u_2\neq v_2$ in $R_2^\times$, then in $R_1\times R_2$ the pairs
$\{(u_1,u_2),(v_1,v_2)\}$ and $\{(u_1,v_2),(v_1,u_2)\}$ are distinct but share a cell.
\end{theorem}
\begin{proof}
Sums and products are componentwise; each component multiset $\{u_i,v_i\}$ is preserved, only the
matching between components changes.
\end{proof}

\begin{proposition}\label{prop:triv}
If $R_1^\times$ is trivial and $R_2$ is Vieta-injective, then $R_1\times R_2$ is Vieta-injective.
\end{proposition}

\begin{theorem}[Conductor classification]\label{thm:class}
$\Z/m\Z$ is Vieta-injective if and only if $m\in\{0,1,2\}$, or $m=\ell$, or $m=2\ell$, with $\ell$ an
odd prime.
\end{theorem}
\begin{proof}[Proof sketch]
($\Leftarrow$) $\Z$ and $\Z/\ell$ are domains; $\Z/1,\Z/2$ have one unit;
$\Z/2\ell\cong\Z/2\times\Z/\ell$ (Proposition~\ref{prop:triv}). ($\Rightarrow$) If $\ell^2\mid m$,
$m=\ell^2c$, then $a=\ell c\neq0$ has $a^2=0$ (Theorem~\ref{thm:nil}). So $m$ is squarefree and has an
odd prime factor $\ell$; write $m=\ell c$ with $c\ge3$ coprime to $\ell$. Then
$\Z/m\cong\Z/\ell\times\Z/c$ and $1\neq-1$ in each factor (Theorem~\ref{thm:match}).
\end{proof}

Enumeration for $1\le m\le 60$ gives exactly $1,2,3,5,6,7,10,11,13,14,17,19,22,23,26,29,31,34,37,
38,41,43,46,47,53,58,59$. There are $4$ colliding cells at $m=8$, $6$ at $m=9$, $6$ at $m=15$ (all of
matching type) and $16$ at $m=16$.

\section{The half-conductor law}

\begin{lemma}[Valuation pigeonhole]\label{lem:pig}
If $\ell$ is prime, $2j\le k+1$ and $\ell^k\mid ab$ in $\Z$, then $\ell^j\mid a$ or $\ell^j\mid b$.
\end{lemma}
\begin{proof}
Otherwise $v_\ell(a)+v_\ell(b)\le 2j-2\le k-1$.
\end{proof}

\begin{theorem}[Half-conductor law]\label{thm:half}
Let $\ell$ be prime and $p,q,p',q'\in\Z$ with $\ell^k\mid(p+q)-(p'+q')$ and $\ell^k\mid pq-p'q'$. Then
$\{p,q\}\equiv\{p',q'\}\pmod{\ell^{\ceilhalf{k}}}$ as unordered pairs.
\end{theorem}
\begin{proof}
By \eqref{eq:key}, $\ell^k\mid(p-p')(p-q')$; Lemma~\ref{lem:pig} with $j=\ceilhalf{k}$ gives
$\ell^j\mid p-p'$ or $\ell^j\mid p-q'$, and the congruence of sums yields the other element.
\end{proof}

\begin{theorem}[Sharpness]\label{thm:sharp}
With $j=\ceilhalf{k}$ and $a=\ell^j$, the pairs $\{1,1\}$ and $\{1+a,1-a\}$ agree in sum and product
modulo $\ell^k$ but $1\not\equiv1\pm a\pmod{\ell^{j+1}}$. Hence if $j+1\le k$ the reduction
$(\Z/\ell^k)^\times\to(\Z/\ell^{j+1})^\times$ is not readable, whereas the reduction to
$(\Z/\ell^j)^\times$ is.
\end{theorem}

