\begin{lemma}[Square-zero rigidity]\label{lem:rigid}
If $f$ is readable on $R^\times$ and $(y-x)^2=0$ for units $x,y$, then $f(x)=f(y)$.
\end{lemma}
\begin{proof}
Let $d=y-x$ and $w=x-d$, a unit since $(x-d)(x+d)=x^2$. The pairs $\{x,x\}$ and $\{y,w\}$ have sum
$2x$ and product $x^2-d^2=x^2$, so $\{f(x),f(x)\}=\{f(y),f(w)\}$.
\end{proof}

\begin{theorem}[Classification at a prime power]\label{thm:ppclass}
A type map on $(\Z/\ell^k)^\times$ is readable iff it depends only on the residue modulo
$\ell^{\ceilhalf{k}}$.
\end{theorem}
\begin{proof}
($\Leftarrow$) Theorem~\ref{thm:half} and Proposition~\ref{prop:coarse}. ($\Rightarrow$) If
$x\equiv y\pmod{\ell^{\ceilhalf{k}}}$ then $\ell^k\mid(y-x)^2$; apply Lemma~\ref{lem:rigid}.
\end{proof}

\begin{theorem}[Discriminant refinement; Hensel form]\label{thm:hensel}
If $t+1\le k$, $\ell^{t+1}\nmid p-q$, and $\ell^k$ divides $(p+q)-(p'+q')$ and $pq-p'q'$, then
$\{p,q\}\equiv\{p',q'\}\pmod{\ell^{k-t}}$. In particular, if $p\not\equiv q\pmod\ell$ the view
modulo $\ell^k$ determines the pair modulo $\ell^k$.
\end{theorem}
\begin{proof}[Proof sketch]
If $\ell^{t+1}$ divided both $p-p'$ and $p-q'$ it would divide
$p-q=(p-p')+(p-q')-((p+q)-(p'+q'))$. So one factor of \eqref{eq:key} has valuation $\le t$ and the
other has valuation $\ge k-t$.
\end{proof}

\section{Conductor 8}\label{sec:eight}

\begin{proposition}[Refutation]\label{prop:refute}
The primes $17,41,13,29$ satisfy $17\cdot41\equiv13\cdot29\equiv1$ and $17+41\equiv13+29\equiv2\pmod 8$,
yet $17\equiv41\equiv1$ and $13\equiv29\equiv5\pmod 8$. So $(pq\bmod8,\ p+q\bmod8)$ does not determine
$p\bmod 8$.
\end{proposition}

Structurally, $8$ is not in the list of Theorem~\ref{thm:class} (indeed $4^2\equiv0$), and modulo
$8$ one has $(x-1)^2\equiv(x-5)^2\equiv x^2-2x+1$.

\begin{lemma}[Vieta fibres at $8$]\label{lem:fib8}
The colliding cells of $\Z/8$ are
$\{1,1\}\sim\{5,5\}$, $\{3,3\}\sim\{7,7\}$, $\{1,3\}\sim\{5,7\}$, $\{1,7\}\sim\{3,5\}$ (four of ten
unordered pairs). Whenever $(p,q)$ and $(p',q')$ share a cell, after possibly swapping
$p'\leftrightarrow q'$ one has $p'\in\{p,5p\}$ and $q'\in\{q,5q\}$.
\end{lemma}

\begin{theorem}[Criterion at conductor $8$]\label{thm:eight}
A type map $f$ on $(\Z/8)^\times$ is readable iff $f(5u)=f(u)$ for every unit $u$, i.e.\ iff $f$
depends only on $p\bmod4$.
\end{theorem}
\begin{proof}
The diagonal collisions $\{1,1\}\sim\{5,5\}$ and $\{3,3\}\sim\{7,7\}$ force $f(1)=f(5)$ and
$f(3)=f(7)$. Conversely every collision in Lemma~\ref{lem:fib8} moves each slot within its
$\langle5\rangle$-orbit.
\end{proof}

\begin{theorem}\label{thm:eightdvd}
If $8\mid m$, every type map on $(\Z/m)^\times$ factoring through $(\Z/4)^\times$ is readable.
\end{theorem}
\begin{proof}
Reduction $m\to4$ factors through $8$; apply Theorem~\ref{thm:half} at $2^3$ and
Proposition~\ref{prop:pull}.
\end{proof}

