\begin{theorem}[Exactly one quadratic channel]\label{thm:quad}
Of the Legendre channels of $\Q(i)$, $\Q(\sqrt2)$, $\Q(\sqrt{-2})$, exactly the first is readable
from the view modulo $8$.
\end{theorem}

For a separable $F\in\Z[x]$ and unramified $p$, the \emph{\'etale type} of $p$ records how each
irreducible factor of $F$ factors modulo $p$. For $F=(x^2+1)(x^2-2)$ it is
$\tau(p)=(\chi_4(p),\chi_8(p))$; the \emph{partition type} is
$\pi(p)=[\chi_4(p)=1]+[\chi_8(p)=1]$; and $x^4+1$, with splitting field $\Q(\zeta_8)$, splits
completely iff $p\equiv1\pmod8$.

\begin{theorem}[Readability is not inherited from factors]\label{thm:etale}
\begin{enumerate}[label=(\alph*)]
\item The \'etale type $\tau$ of $(x^2+1)(x^2-2)$ is not readable, although $\chi_4$ is.
\item The partition type $\pi$ is not readable.
\item The complete-splitting indicator of $x^4+1$ is not readable.
\end{enumerate}
\end{theorem}
\begin{proof}
(a) $\chi_8$ is a coarsening of $\tau$; use Theorem~\ref{thm:quad}. (b),(c) Both fail
$\times5$-invariance at $u=1$: $\pi(1)=2\neq1=\pi(5)$, and $1\equiv1$ but $5\not\equiv1\pmod8$.
\end{proof}

\section{Combining channels}\label{sec:join}

\begin{theorem}[Join failure]\label{thm:join}
For distinct odd primes $\ell_1,\ell_2$ and $m=\ell_1\ell_2$, the channels $p\bmod\ell_1$ and
$p\bmod\ell_2$ are each readable, but $p\mapsto(p\bmod\ell_1,p\bmod\ell_2)$ is not. For example at
$m=15$.
\end{theorem}
\begin{proof}
Single channels are pullbacks from fields. The joint channel is injective (CRT), so its readability
would contradict Theorem~\ref{thm:class} via Proposition~\ref{prop:inj}.
\end{proof}

\begin{lemma}[Swap dichotomy]\label{lem:swap}
If $g:X\times Y\to B$ satisfies $\{g(x,y),g(x',y')\}=\{g(x,y'),g(x',y)\}$ for all $x,x',y,y'$, then
$g$ is independent of $y$ or independent of $x$.
\end{lemma}
\begin{proof}
Suppose $g(x_0,y_1)\neq g(x_0,y_2)$ and $g(x_1,y_0)\neq g(x_2,y_0)$. The hypothesis at
$(x_0,x',y_1,y_2)$ must use the crossed matching, so $g(x',y_1)=g(x_0,y_1)$ for all $x'$. At
$(x_1,x_2,y_1,y_0)$ either matching then gives $g(x_1,y_0)=g(x_2,y_0)$, a contradiction.
\end{proof}

\begin{theorem}[Product classification]\label{thm:prod}
A type map on $(R_1\times R_2)^\times$ is readable iff it equals $h\circ\mathrm{pr}_1$ with $h$
readable on $R_1^\times$, or $h\circ\mathrm{pr}_2$ with $h$ readable on $R_2^\times$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:match} the hypothesis of Lemma~\ref{lem:swap} holds, so $f$ depends on one
component; the induced $h(u)=f(u,1)$ is readable since collisions in $R_1$ lift by pairing with $1$.
The converse is Proposition~\ref{prop:pull}.
\end{proof}

\begin{corollary}\label{cor:coprime}
If $\gcd(a,b)=1$, a type map on $(\Z/ab)^\times$ is readable iff it is a readable map of the residue
modulo $a$ or a readable map of the residue modulo $b$.
\end{corollary}

\begin{corollary}
For distinct primes $\ell_1,\ell_2$, a type map on $(\Z/\ell_1^{k_1}\ell_2^{k_2})^\times$ is readable
iff it depends only on the residue modulo $\ell_1^{\ceilhalf{k_1}}$ or only on the residue modulo
$\ell_2^{\ceilhalf{k_2}}$.
\end{corollary}

\begin{theorem}[Readable channels at every conductor]\label{thm:general}
Let $m\ge1$. A type map $f$ on $(\Z/m)^\times$ is readable iff there are a prime $\ell$ and $k\ge0$
with $\ell^k\mid m$, $\gcd(m/\ell^k,\ell)=1$, such that $x\equiv y\pmod{\ell^{\ceilhalf{k}}}$ implies
$f(x)=f(y)$.
\end{theorem}
\begin{proof}[Proof sketch]
($\Leftarrow$) Reduction $m\to\ell^k\to\ell^{\ceilhalf{k}}$ is readable; $f$ is a coarsening.
($\Rightarrow$) Strong induction on $m$; $m=1$ is trivial. Let $\ell$ be the least prime factor,
$\ell^k\,\|\,m$, $r=m/\ell^k<m$. By Corollary~\ref{cor:coprime}, $f$ is a readable map of the residue
mod $\ell^k$ (then Theorem~\ref{thm:ppclass}) or a readable map $h$ of the residue mod $r$; the
induction hypothesis gives $\ell'^{k'}\,\|\,r$ with $\ell'\neq\ell$, hence $\ell'^{k'}\,\|\,m$. If
$k'=0$ then $h$ is constant and any witness works.
\end{proof}

\begin{example}
At $m=24=2^3\cdot3$ readable channels are functions of $p\bmod4$ or of $p\bmod3$, never both:
$p\bmod 2,3,4,6$ are readable, $p\bmod 8,12,24$ are not. A brute-force comparison of the criterion
with the definition on $3487$ type maps at conductors $2\le m\le48$ found complete agreement.
\end{example}

\section{Algorithms}
\textbf{A (brute force).} Bucket the $\binom{\varphi(m)+1}{2}$ unordered unit pairs by cell and check
that $\{f(p),f(q)\}$ is constant on each bucket; time $O(\varphi(m)^2)$.

\textbf{B (by classification).} Factor $m=\prod\ell_i^{k_i}$; for each $i$ test whether $f$ is
constant on fibres of $u\mapsto u\bmod\ell_i^{\ceilhalf{k_i}}$; accept iff some $i$ succeeds. Time
$O(\omega(m)\varphi(m))$ after factoring; correct by Theorem~\ref{thm:general}.

\textbf{C (maximal resolution).} Return the largest $r\mid m$ whose reduction is readable. At
$\ell^k$ this is $\ell^{\ceilhalf{k}}$; at composite $m$ a harmless factor $2$ may appear (at $m=24$
the answer is $6$, since units modulo $6$ carry the same information as units modulo $3$).

\section{Discussion}
The hinted view sees a single prime-power component of the conductor at half resolution. This
explains why routing is dial-dependent: a dial living on that component at that resolution is
readable from the sum, others need the combination with further information. If a dial at
conductor $8$ is exactly sum-sufficient, Theorem~\ref{thm:eight} says it sees only $p\bmod4$---the
$\Q(i)$ layer. Nilpotents cost resolution, CRT splittings cost matching; Theorem~\ref{thm:general}
combines both effects. Because the \'etale type of $F_1F_2$ is the join of the factor types and
readability is not closed under joins, reducible polynomials typically have unreadable type
channels. The theorems concern the hinted view of residues; they do not by themselves compute
empirical percentages from finite prime samples.

\section{Future work}
\begin{enumerate}[label=(\arabic*)]
\item \emph{$n$-tuple dials.} With $e_1,\dots,e_n$ known modulo $m=\prod\ell_i^{k_i}$, conjecturally
a type map is readable iff it factors through $(\Z/\ell_i^{\lceil k_i/n\rceil})^\times$ for a single
$i$ (odd $\ell_i>n$); the swap dichotomy should generalise to mixed permutations.
\item \emph{Collision counts} in closed form (data: $4,6,6,16$ at $m=8,9,15,16$).
\item \emph{Number-field residue rings}, where non-abelian dials depend on Frobenius classes.
\item \emph{Statistical readability}: relate exact readability to empirical carried fractions.
\end{enumerate}

