from math import gcd
from typing import List, Tuple


def is_prime(n: int) -> bool:
    return n >= 2 and all(n % d for d in range(2, int(n ** 0.5) + 1))


def disguised_prime_pairs(p: int, q: int, m: int, bound: int = 200) -> List[Tuple[int, int]]:
    """Prime pairs (p', q') below `bound` with the same (p+q, pq) mod m as (p, q) but a different
    unordered residue pair mod m."""
    s, n = (p + q) % m, (p * q) % m
    target = sorted((p % m, q % m))
    ps = [x for x in range(3, bound) if is_prime(x) and gcd(x, m) == 1]
    out: List[Tuple[int, int]] = []
    seen = set()
    for i, a in enumerate(ps):
        for b in ps[i:]:
            if (a + b) % m == s and (a * b) % m == n:
                res = tuple(sorted((a % m, b % m)))
                if list(res) != target and res not in seen:
                    seen.add(res)
                    out.append((a, b))
    return out


if __name__ == "__main__":
    print("Refuting 'the sum determines p mod 8':")
    for a, b in disguised_prime_pairs(17, 41, 8):
        print(f"  {{17, 41}} and {{{a}, {b}}}: same hint mod 8, residues {{1,1}} vs {{{a % 8},{b % 8}}}")
    print("Half-conductor law check: every disguised pair still agrees mod 4:")
    print(all(sorted((a % 4, b % 4)) == [1, 1] for a, b in disguised_prime_pairs(17, 41, 8)))
    print("At a prime conductor there are no disguises:", disguised_prime_pairs(17, 41, 13))

