from collections import defaultdict
from math import gcd
from typing import Callable, Dict, Hashable, List, Tuple


def units(m: int) -> List[int]:
    return [0] if m == 1 else [a for a in range(m) if gcd(a, m) == 1]


def hinted_cells(m: int) -> Dict[Tuple[int, int], List[Tuple[int, int]]]:
    """Bucket unordered unit pairs {p, q} by their hinted view (p+q, pq) mod m."""
    cells: Dict[Tuple[int, int], List[Tuple[int, int]]] = defaultdict(list)
    U = units(m)
    for i, p in enumerate(U):
        for q in U[i:]:
            cells[((p + q) % m, (p * q) % m)].append((p, q))
    return cells


def is_readable_bruteforce(f: Callable[[int], Hashable], m: int) -> bool:
    """A type map is readable iff the multiset {f(p), f(q)} is constant on every cell."""
    for pairs in hinted_cells(m).values():
        seen = {tuple(sorted((repr(f(p)), repr(f(q))))) for p, q in pairs}
        if len(seen) > 1:
            return False
    return True


if __name__ == "__main__":
    chi4 = lambda p: 1 if p % 4 == 1 else -1
    chi8 = lambda p: 1 if p % 8 in (1, 7) else -1
    print("chi_4 readable at 8:", is_readable_bruteforce(chi4, 8))   # True
    print("chi_8 readable at 8:", is_readable_bruteforce(chi8, 8))   # False

from math import gcd
from typing import Callable, Dict, Hashable, List, Optional, Tuple


def units(m: int) -> List[int]:
    return [0] if m == 1 else [a for a in range(m) if gcd(a, m) == 1]


def factorize(m: int) -> Dict[int, int]:
    out: Dict[int, int] = {}
    d = 2
    while d * d <= m:
        while m % d == 0:
            out[d] = out.get(d, 0) + 1
            m //= d
        d += 1
    if m > 1:
        out[m] = out.get(m, 0) + 1
    return out


def factors_through(f: Callable[[int], Hashable], m: int, r: int) -> bool:
    seen: Dict[int, Hashable] = {}
    for u in units(m):
        v = f(u)
        if u % r in seen and seen[u % r] != v:
            return False
        seen.setdefault(u % r, v)
    return True


def readable_layer(f: Callable[[int], Hashable], m: int) -> Optional[Tuple[int, int, int]]:
    """Return (l, k, l^ceil(k/2)) for a prime power l^k || m through whose half-resolution
    f factors, or None if f is not readable (general classification theorem)."""
    if m == 1:
        return (1, 0, 1)
    for l, k in factorize(m).items():
        r = l ** ((k + 1) // 2)
        if factors_through(f, m, r):
            return (l, k, r)
    return None


if __name__ == "__main__":
    print(readable_layer(lambda p: p % 4, 24))        # (2, 3, 4)
    print(readable_layer(lambda p: p % 3, 24))        # (3, 1, 3)
    print(readable_layer(lambda p: p % 12, 24))       # None: two layers at once

from math import gcd
from typing import List


def units(m: int) -> List[int]:
