def pairs_agree_mod(a: int, b: int, c: int, d: int, r: int) -> bool:
    return ((a - c) % r == 0 and (b - d) % r == 0) or ((a - d) % r == 0 and (b - c) % r == 0)


def maximal_resolution(m: int) -> int:
    """Largest r | m such that the hinted view mod m determines {p, q} mod r."""
    cells = {}
    U = units(m)
    for i, p in enumerate(U):
        for q in U[i:]:
            cells.setdefault(((p + q) % m, (p * q) % m), []).append((p, q))
    best = 1
    for r in range(1, m + 1):
        if m % r:
            continue
        if all(pairs_agree_mod(*v[0], *w, r) for v in cells.values() for w in v):
            best = r
    return best


