Vieta-injective (none), nilpotent (a square divides m), matching (two coprime factors >= 3), or both."""
from math import gcd
import matplotlib.pyplot as plt


def units(m: int) -> list[int]:
    return [0] if m == 1 else [a for a in range(m) if gcd(a, m) == 1]


def colliding(m: int) -> int:
    cells: dict[tuple[int, int], int] = {}
    U = units(m)
    for i, p in enumerate(U):
        for q in U[i:]:
            k = ((p + q) % m, (p * q) % m)
            cells[k] = cells.get(k, 0) + 1
    return sum(1 for v in cells.values() if v > 1)


def factorize(m: int) -> dict[int, int]:
    out: dict[int, int] = {}
    d = 2
    while d * d <= m:
        while m % d == 0:
            out[d] = out.get(d, 0) + 1
            m //= d
        d += 1
    if m > 1:
        out[m] = out.get(m, 0) + 1
    return out


def obstruction(m: int) -> str:
    f = factorize(m)
    nil = any(k >= 2 for k in f.values())
    big = [l ** k for l, k in f.items() if l ** k >= 3]
    match = len(big) >= 2
    return {(False, False): "none", (True, False): "nilpotent", (False, True): "matching",
            (True, True): "both"}[(nil, match)]


colors = {"none": "#2ca02c", "nilpotent": "#d62728", "matching": "#1f77b4", "both": "#9467bd"}
ms = list(range(1, 81))
vals = [colliding(m) for m in ms]
obs = [obstruction(m) for m in ms]
plt.figure(figsize=(12, 4.5))
for kind, c in colors.items():
    xs = [m for m, o in zip(ms, obs) if o == kind]
    ys = [v for v, o in zip(vals, obs) if o == kind]
    plt.bar(xs, ys, color=c, label=kind)
plt.xlabel("conductor m")
plt.ylabel("colliding cells")
plt.title("Where the hint (p+q, pq) mod m forgets the pair: the two obstructions")
plt.legend()
plt.tight_layout()
plt.show()
